pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address recipient, address payer1, address payer2) public {
        vm.assume(recipient != address(0));
        vm.assume(payer1 != address(0) && payer2 != address(0));
        amount1 = bound(amount1, 1, 1e30);
        amount2 = bound(amount2, 1, 1e30);

        vm.prank(payer1);
        c.supplyTokenTo(amount1, recipient);
        vm.prank(payer2);
        c.supplyTokenTo(amount2, recipient);

        // With exchange rate 1e18 in the stub, credits issued per deposit equal the amount deposited.
        // General rule: imBalances(recipient) accumulates ALL credits ever issued to it.
        assertTrue(c.imBalances(recipient) == amount1 + amount2);
    }
}
